#include <vector>
#include <map>
#include <set>
#include <string>
#include <algorithm>
#include <stdexcept>
struct Version{int value,version;std::string writer;};struct Read{std::string key;Version row;};struct Tx{int snapshot=-1;std::string state="active";std::map<std::string,int>writes;std::vector<Read>reads;};
struct MVCC{std::string isolation;int clock=0;std::map<std::string,std::vector<Version>>versions{{"x",{{1,0,""}}},{"y",{{1,0,""}}}};std::map<std::string,Tx>transactions;explicit MVCC(std::string iso):isolation(iso){}void begin(std::string id){if(!transactions.emplace(id,Tx{}).second)throw std::invalid_argument("ID reused");}Tx& active(std::string id){auto& t=transactions.at(id);if(t.state!="active")throw std::logic_error("not active");if(t.snapshot<0)t.snapshot=clock;return t;}bool snapshot(){return isolation=="repeatable-read"||isolation=="serializable";}void write(std::string id,std::string key,int value){active(id).writes[key]=value;}int read(std::string id,std::string key){auto& t=active(id);if(t.writes.count(key))return t.writes.at(key);int limit=snapshot()?t.snapshot:clock;auto row=versions.at(key).front();for(auto v:versions.at(key))if(v.version<=limit)row=v;t.reads.push_back({key,row});return row.value;}
int writeVersion(std::string id,std::string key,std::string candidate){if(id==candidate)return clock+1;for(auto v:versions.at(key))if(v.writer==id)return v.version;throw std::logic_error("missing write");}
bool cycle(std::string candidate){std::vector<std::string>nodes;for(auto [id,t]:transactions)if(t.state=="committed"||id==candidate)nodes.push_back(id);std::set<std::pair<std::string,std::string>>edges;for(auto reader:nodes)for(auto r:transactions.at(reader).reads){if(!r.row.writer.empty()&&r.row.writer!=reader)edges.insert({r.row.writer,reader});for(auto writer:nodes)if(writer!=reader&&transactions.at(writer).writes.count(r.key)&&writeVersion(writer,r.key,candidate)>r.row.version)edges.insert({reader,writer});}for(std::string key:{"x","y"}){std::vector<std::string>writers;for(auto id:nodes)if(transactions.at(id).writes.count(key))writers.push_back(id);std::sort(writers.begin(),writers.end(),[&](auto a,auto b){return writeVersion(a,key,candidate)<writeVersion(b,key,candidate);});for(unsigned i=1;i<writers.size();i++)edges.insert({writers[i-1],writers[i]});}return edges.count({"A","B"})&&edges.count({"B","A"});}
bool commit(std::string id){auto& t=active(id);bool conflict=false;if(snapshot())for(auto [key,value]:t.writes)if(versions.at(key).back().version>t.snapshot)conflict=true;if(conflict||(isolation=="serializable"&&cycle(id))){rollback(id);return false;}if(!t.writes.empty()){clock++;for(auto [key,value]:t.writes)versions.at(key).push_back({value,clock,id});}t.state="committed";return true;}void rollback(std::string id){auto& t=active(id);t.writes.clear();t.state="aborted";}};
// Validated A/B and x/y operations; no physical locking, WAL or complete PostgreSQL SSI.
